from gklib import L, S, Q
L("health","eat-well-sleep-well-move-well","8-10","Eat Well, Sleep Well, Move Well","The three habits that keep your body and mind strong.","🥗",[
 S("A balanced plate","Our body needs carbohydrates for energy, proteins to grow and repair, fats in small amounts and vitamins and minerals to stay healthy. | A good plate has grains, pulses or eggs or milk, vegetables and fruits. | Drinking enough water helps every part of the body.",["Energy, growth, protection","Colourful plate","Water"]),
 S("Eat the rainbow","Different coloured fruits and vegetables give different vitamins. | Try something green, something orange and something red each day. | Sweets, chips and fizzy drinks are fine now and then, but they should not replace real meals.",["Many colours","Sweets only sometimes"]),
 S("Move your body","Children should get about an hour of active play every day. | Running, cycling, skipping and sports make your heart, bones and muscles stronger. | Moving also helps you feel happier and think better.",["About 60 minutes of activity","Stronger heart and bones"]),
 S("Sleep","While you sleep your body grows and your brain stores what you learned. | Try to go to bed at the same time every day and put screens away an hour before sleep. | Wash your hands before meals and brush your teeth twice a day.",["Sleep helps growth and memory","Screens off before bed","Wash hands"]),
],facts=["Your bones stop growing taller in your late teens but keep renewing all your life.","Millets such as ragi and kambu are rich in minerals and have been eaten in Tamil Nadu for centuries.","Laughing and playing with friends are good for health too."],
quiz=[Q("About how much active play should children get daily?",["10 minutes","About an hour","5 hours"],1,"Experts suggest about 60 minutes a day."),
Q("What helps your body grow and repair?",["Proteins","Only sugar","Nothing"],0,"Proteins help build and repair the body."),
Q("What should you do before meals?",["Wash your hands","Run around","Watch a screen"],0,"Washing hands removes germs.")],tags=["food","sleep","exercise"],notes="General healthy-living information for children. For medical questions, ask a doctor.")

L("health","stay-safe-road-fire-and-online","8-10","Staying Safe: Roads, Fire and Online","Simple rules that can protect you at home, on the road and on the internet.","🚦",[
 S("On the road","Always walk on the footpath, and cross at a zebra crossing or where there is a signal. | Look right, look left and look right again before you cross. | When you ride in a car or on a two-wheeler, wear a seat belt or a helmet every time.",["Footpath and crossing","Look before crossing","Seat belt or helmet"]),
 S("Fire safety","Never play with matches, lighters or crackers. | If there is a fire, get out, stay out and call 101 for the fire brigade, or 112, India's emergency number. | If clothes catch fire, stop, drop and roll.",["Never play with fire","Call 101 or 112","Stop, drop and roll"]),
 S("Online safety","Do not share your address, school or phone number with people you only know online. | Never share your passwords, except with your parents. | If something online makes you feel scared or uncomfortable, tell a trusted adult at once.",["Keep personal details private","Tell an adult"]),
 S("Trust your feelings","If something feels wrong, you can say no and walk away. | Know the phone number of a trusted adult by heart. | In India, Childline 1098 is a free helpline for any child who needs help.",["You can say no","Childline 1098"]),
],facts=["112 is the all-in-one emergency number across India.","A helmet can greatly reduce the risk of serious head injury.","Strong passwords are long and mix words, numbers and symbols."],
quiz=[Q("Which number is for the fire brigade in India?",["101","1098","100"],0,"101 reaches the fire service."),
Q("What should you do if you feel unsafe online?",["Tell a trusted adult","Keep it secret","Reply to the stranger"],0,"Tell a trusted adult right away."),
Q("What is the all-in-one emergency number in India?",["112","123","999"],0,"112 is the national emergency number.")],tags=["safety","road","online"],asof="November 2026",notes="Helpline numbers are as given by the Government of India at the time of writing; check that they are still in use.")

L("arts","colours-and-how-to-mix-them","5-7","Colours and How to Mix Them","Primary colours, mixing, and warm and cool colours.","🎨",[
 S("Three primary colours","In painting, the three primary colours are red, yellow and blue. | You cannot make them by mixing other colours. | All other paint colours can be made from them.",["Red, yellow, blue"]),
 S("Mixing","Red and yellow make orange. | Yellow and blue make green. | Blue and red make purple, and these are called secondary colours.",["Red + yellow = orange","Yellow + blue = green","Blue + red = purple"]),
 S("Light and dark","Add white to a colour to make it lighter, and add a tiny bit of black or a darker colour to make it darker. | A colour with white added is called a tint. | Try making five shades of blue.",["Add white: lighter","Add dark: darker"]),
 S("Warm and cool","Red, orange and yellow are warm colours that remind us of fire and sun. | Blue, green and purple are cool colours that remind us of water and grass. | Artists use them to show mood.",["Warm colours","Cool colours"]),
],facts=["Light mixes differently to paint: the primary colours of light are red, green and blue.","The kolam designs outside Tamil homes often use rice flour in white and sometimes bright colours.","Rangoli designs use coloured powders and petals."],
quiz=[Q("What do red and yellow make?",["Orange","Green","Purple"],0,"Red and yellow make orange."),
Q("Which is a cool colour?",["Blue","Red","Orange"],0,"Blue is a cool colour."),
Q("Which is a primary colour?",["Green","Yellow","Pink"],1,"Yellow is a primary colour.")],tags=["colour","art"])

L("arts","sounds-of-music-notes-and-rhythm","8-10","The Sounds of Music: Notes, Rhythm and Raga","Pitch, beat and the seven notes in both Western and Indian music.","🎶",[
 S("Music is organised sound","Music is made of sounds arranged in time. | The three main parts are pitch, how high or low a note is, rhythm, the pattern of beats, and tempo, how fast or slow it is. | Singing, clapping and drumming all use them.",["Pitch","Rhythm","Tempo"]),
 S("Seven notes","Western music names its notes A B C D E F G. | Indian classical music uses seven basic notes: sa, ri, ga, ma, pa, dha and ni. | In Carnatic music these are called swaras.",["A to G","Sa ri ga ma pa dha ni"]),
 S("Raga and tala","A raga is a set of notes and rules for how to use them, and it creates a special mood. | A tala is the cycle of beats that keeps time, such as adi tala with eight beats. | Together they allow musicians to improvise and still stay in order.",["Raga: notes and mood","Tala: beat cycle"]),
 S("Instruments","The veena, violin and flute carry the melody, and the mridangam and tabla keep the rhythm. | Instruments are grouped as strings, winds, percussion and keyboards. | Trying any instrument, even a simple drum, trains your ears and your patience.",["Melody and rhythm instruments","Four main groups"]),
],facts=["Tamil Nadu has a very old musical tradition, and the Chennai Music Season in December is one of the largest classical music festivals in the world.","The tabla and the mridangam are both drums, but they come from different traditions.","A metronome is a device that clicks a steady beat."],
quiz=[Q("What is tempo?",["How fast or slow music is","How loud it is","Who sings"],0,"Tempo is the speed of the music."),
Q("How many basic notes does Indian classical music use?",["Seven","Five","Twelve"],0,"Sa, ri, ga, ma, pa, dha, ni."),
Q("Which one is a drum?",["Mridangam","Veena","Violin"],0,"The mridangam is a drum.")],tags=["music","raga","rhythm"])

L("words","how-languages-grow-and-where-words-come-from","11-13","Where Words Come From","How languages change, borrow words and keep growing, with Tamil and English examples.","🔤",[
 S("Languages are alive","Languages change over time, just like people do. | New words come when we need them, like 'selfie' or 'online'. | Old words fade when we stop using them.",["Languages change","New words appear"]),
 S("Borrowed words","English has borrowed words from many languages, including Tamil. | The words 'catamaran', 'curry', 'cheroot' and 'mango' are all believed to come from Tamil. | Tamil, in turn, uses words like 'bus', 'school' and 'computer' from English.",["Tamil gave English words","English gave Tamil words"]),
 S("Word parts","Many English words are built from roots, prefixes and suffixes. | For example 'un' means not, 'happy' is the root, so 'unhappy' means not happy. | Knowing common parts helps you guess new words.",["Prefix + root + suffix","Guess the meaning"]),
 S("Language families","Languages are grouped in families. | Tamil, Telugu, Kannada and Malayalam belong to the Dravidian family. | Hindi, Bengali and English belong to the large Indo-European family.",["Families of languages","Dravidian and Indo-European"]),
],facts=["Tamil is among the world's oldest surviving classical languages and has literature more than two thousand years old.","India's Constitution lists 22 official languages in the Eighth Schedule.","The English word 'orange' came through several languages from a Sanskrit and Dravidian source word."],
quiz=[Q("Which English word comes from Tamil?",["Catamaran","Banana split","Telephone"],0,"Catamaran comes from the Tamil word kattumaram."),
Q("What does the prefix 'un' usually mean?",["Not","Again","Before"],0,"Un means not."),
Q("Tamil belongs to which language family?",["Dravidian","Indo-European","Semitic"],0,"Tamil is Dravidian.")],tags=["language","tamil","words"],notes="Word origins are summarised from standard dictionaries; some word histories are debated.")

L("words","become-a-better-reader","8-10","Become a Better Reader","Five tricks to understand and remember what you read.","📚",[
 S("Look before you read","Look at the title, the headings and the pictures first. | Ask yourself what you already know about the topic. | This gives your brain a map of what is coming.",["Preview first","Think what you already know"]),
 S("Ask questions","As you read, ask who, what, where, when, why and how. | Stop after each paragraph and say it in your own words. | If you cannot, read it again more slowly.",["Ask questions","Say it in your own words"]),
 S("Unknown words","When you meet a new word, look at the words around it for clues. | Look for parts you know, like a prefix or root. | Then check a dictionary and write the word with an example sentence.",["Use clues","Check a dictionary"]),
 S("Remember it","After reading, write three main points or draw a quick picture. | Tell the story to someone else. | Reading a little every day is better than a lot once a week.",["Summarise","Teach someone","Read daily"]),
],facts=["Reading for just 20 minutes a day means you read well over a million words in a year.","Reading aloud helps younger readers with pronunciation and understanding.","Libraries, including free public libraries, can lend you books at no cost."],
quiz=[Q("What should you do before reading?",["Look at the title and headings","Skip to the end","Close the book"],0,"Previewing helps you predict."),
Q("What can you do with a new word?",["Look for clues in the sentence","Ignore it forever","Guess wildly"],0,"The surrounding words give clues."),
Q("How often is it best to read?",["A little every day","Once a year","Never"],0,"Regular practice builds skill.")],tags=["reading","study"])
